<?php require __DIR__.'/../app/bootstrap.php';require_login();require_permission('inspections.edit');verify_csrf();$uid=(int)$_POST['unit_id'];$duration=0;if(!empty($_POST['start_time'])&&!empty($_POST['end_time'])){$a=strtotime($_POST['start_time']);$b=strtotime($_POST['end_time']);if($b<$a)$b+=86400;$duration=round(($b-$a)/3600,2);}$old=$pdo->prepare('SELECT operational_status FROM units WHERE id=?');$old->execute([$uid]);$oldStatus=$old->fetchColumn();$pdo->prepare('INSERT INTO condition_events(unit_id,event_date,status,start_time,end_time,duration_hours,cause,action_taken) VALUES(?,?,?,?,?,?,?,?)')->execute([$uid,$_POST['event_date'],$_POST['status'],($_POST['start_time']??'')?:null,($_POST['end_time']??'')?:null,$duration,trim($_POST['cause']??''),trim($_POST['action_taken']??'')]);$eventId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE units SET operational_status=? WHERE id=?')->execute([$_POST['status'],$uid]);add_history($pdo,'unit',$uid,$oldStatus,$_POST['status'],'Condition event #'.$eventId);audit($pdo,'CREATE','condition_event',$eventId,$_POST['status']);flash('success','Condition monitoring disimpan.');redirect('../'.page_url('condition'));
